import{_ as i,l as n,o as e,c as l,v as t,p as d,x as o,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"债权人协调与空壳债权人","description":"","frontmatter":{"title":"债权人协调与空壳债权人","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/creditor-coordination-empty-creditor.md","filePath":"econ/creditor-coordination-empty-creditor.md","lastUpdated":1789023840000}'),c={name:"econ/creditor-coordination-empty-creditor.md"};function h(D,a,m,A,B,u){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="债权人协调与空壳债权人" tabindex="-1">债权人协调与空壳债权人 <a class="header-anchor" href="#债权人协调与空壳债权人" aria-label="Permalink to &quot;债权人协调与空壳债权人&quot;">​</a></h1><div class="epigraph"><p>分散的债权人难以同意减记；若有人用信用违约互换对冲到「违约更赚钱」，他更会阻止有效重整——债权人身份与经济敞口分家。</p><footer>—— Hu and Black, Debt, Equity, and Hybrid Decoupling, 2008 前后的空壳债权人论述；Bolton and Oehmke, Credit Default Swaps and the Empty Creditor Problem, Review of Financial Studies 2011</footer></div><p><a href="/econ/chapter-11">上一课</a>给出法庭如何用表决克服持出。本课缺口是敞口被衍生品拆开：空壳债权人（empty creditor）持有投票权或法律地位，净经济头寸为零或为负。资本结构动态单元到此收束。不重写 DIP 程序，不把 CDS 定价做成衍生品课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持出已经使私下重组失败。CDS 让债权人把信用风险卖掉，仍保留债券或贷款上的法律权利。Hu–Black：法律权利与经济敞口 decoupling。Bolton–Oehmke：有 CDS 时，债权人更硬，可能过度阻止 Renegotiation，无效率违约上升；但强硬也可能事前抑制策略性违约。缺口是：第 11 章的表决假设投票者希望最大化债券回收；空壳后这个目标函数错了。</p><p><span class="marginnote">协调：集体行动条款、信托人、银团代理，是为把分散变集中。对冲与债权交易把集中再拆开。证券化 OTD 把同一贷款切给许多档，协调面更碎。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事前：CDS 降低持债成本、扩大债务容量，像保险。事后：净空头或不充分对冲的持券人拒绝减记，迫使违约以触发 CDS。政策与合同：披露净敞口、表决时看经济利益，是补丁，本课只标激励。对企业：发行时要预期债权人可能被对冲，条款与关系银行的价值上升——因为银行更难完全空壳（监管与关系）。</p>',8)),(e(),d(E,null,{default:o(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E5%88%86%E6%95%A3%E6%8C%81%E6%9C%89%22%5D%20--%3E%20HOLD%5B%22%E6%8C%81%E5%87%BA%22%5D%0A%20%20CDS%5B%22CDS%20%E5%AF%B9%E5%86%B2%22%5D%20--%3E%20EMPTY%5B%22%E6%9D%83%E5%88%A9%E4%B8%8E%E6%95%9E%E5%8F%A3%E5%88%86%E5%AE%B6%22%5D%0A%20%20EMPTY%20--%3E%20HARD%5B%22%E6%9B%B4%E7%A1%AC%E7%9A%84%E8%B0%88%E5%88%A4%22%5D%0A%20%20HARD%20--%3E%20INEFF%5B%22%E6%97%A0%E6%95%88%E7%8E%87%E6%B8%85%E7%AE%97%20%2F%20%E8%BF%9D%E7%BA%A6%22%5D%0A%20%20HARD%20--%3E%20DISC%5B%22%E4%B9%9F%E5%8F%AF%E8%83%BD%E6%8A%91%E5%88%B6%E7%AD%96%E7%95%A5%E6%80%A7%E8%BF%9D%E7%BA%A6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与展期：空壳加上到期墙，拒绝展期的激励更强。与评级悬崖：触发 CDS 的定义（信用事件）成为合同设计对象，类似评级焦点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是控制权与现金流权在<strong>债权人之间</strong>的楔子——治理单元会对股权讲同一句话（双层股权）。这里楔子由衍生品制造。Bolton–Oehmke 的两面：保险提高事前后视的清偿纪律，也提高事后无效率。最优 CDS 规模不是零，也不是把全体债权人掏空。</p><p>宏观课序的衍生品与影子银行提供市场；本课是企业重组里的微观激励。不要把 CDS 市场微观结构写进本栏。</p><h3 id="空壳不是「对冲的人都是坏人」" tabindex="-1">空壳不是「对冲的人都是坏人」 <a class="header-anchor" href="#空壳不是「对冲的人都是坏人」" aria-label="Permalink to &quot;空壳不是「对冲的人都是坏人」&quot;">​</a></h3><p>对冲是风险管理课（后课公司对冲）的正当工具。问题是<strong>投票权未随敞口走</strong>。完全对冲且仍主导重组投票，目标函数与企业价值最大化脱节。关系贷款加限制转让，是古老的反空壳技术。</p><p><span class="marginnote">本单元从 Leland 的单一债权人边界，走到分散、评级、OTD、法庭、空壳。下一单元问股权侧谁说了算：董事会与接管，对应债权侧刚刚写完的监督与协调。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课结束「债务的时间维度」。不要估计 CDS 基差交易。治理单元从董事会开始，不再加债务条款。公司金融进阶仍停在企业合同，不进入限价簿。</p><p>后课默认：重组效率取决于债权人敞口与权利是否对齐；CDS 可以制造空壳。条款、关系、集中持有是缓解。第 11 章多数决在空壳下也会投错方向。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分散导致持出；CDS 使法律权利与经济敞口脱钩，谈判可能过硬。</li><li>事前保险与事后无效率并存；最优不是禁止对冲。</li><li>债务单元收束：动态权衡、期限、契约、谁是债权人、评级、OTD、重整与协调已经齐。</li><li>出处：Hu and Black；Bolton and Oehmke, <em>RFS</em> 2011。</li></ul>',12))])}const S=i(c,[["render",h]]);export{C as __pageData,S as default};
